 }

+void ApplicationIntegration::addEvent(QDate date)
+{
+    if (!m_calendarService) {
+        return;
+    }
+
+    // Only KOrganizer can be asked to open its event editor on a given day; other applications are just launched
+    if (m_calendarService->desktopEntryName() != "org.kde.korganizer"_L1) {
+        launchCalendar();
+        return;
+    }
+
+    const QString service = u"org.kde.korganizer"_s;
+    const auto openEventEditor = [service, date] {
+        QDBusMessage goDate = QDBusMessage::createMethodCall(service, u"/Calendar"_s, u"org.kde.Korganizer.Calendar"_s, u"goDate"_s);
+        goDate << QVariant::fromValue(date);
+        QDBusConnection::sessionBus().send(goDate);
+        QDBusConnection::sessionBus().send(QDBusMessage::createMethodCall(service, u"/Calendar"_s, u"org.kde.Korganizer.Calendar"_s, u"openEventEditor"_s));
+    };
+
+    if (QDBusConnection::sessionBus().interface()->isServiceRegistered(service)) {
+        openEventEditor();
+        return;
+    }
+
+    auto watcher = new QDBusServiceWatcher(service, QDBusConnection::sessionBus(), QDBusServiceWatcher::WatchForRegistration, this);
+    connect(watcher, &QDBusServiceWatcher::serviceRegistered, watcher, [watcher, openEventEditor] {
+        openEventEditor();
+        watcher->deleteLater();
+    });
+    QTimer::singleShot(std::chrono::minutes(1), watcher, &QObject::deleteLater);
+    launchCalendar();
+}
+
 void ApplicationIntegration::refresh()
 {
     KService::Ptr newService = KApplicationTrader::preferredService(QStringLiteral("text/calendar"));
